package br.com.tapeteskalke.controller; import br.com.tapeteskalke.dto.*; import br.com.tapeteskalke.dto.PermissionDtos.UpdateRequest; import br.com.tapeteskalke.service.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/configuracoes") public class ConfiguracaoController { private final PermissionService permissions; private final PermissionAdminService admin; private final ConfiguracaoLojaService loja; public ConfiguracaoController(PermissionService permissions,PermissionAdminService admin,ConfiguracaoLojaService loja){this.permissions=permissions;this.admin=admin;this.loja=loja;} @GetMapping public ApiResponse<?> get(){permissions.page("configuracoes");return ApiResponse.ok(java.util.Map.of("theme","light","pages",permissions.pages(),"actions",permissions.actions()));} @GetMapping("/permissoes") public ApiResponse<?> permissions(){return ApiResponse.ok(java.util.Map.of("pages",permissions.pages(),"actions",permissions.actions()));} @GetMapping("/permissoes/todas") public ApiResponse<?> matrix(){return ApiResponse.ok(admin.matrix());} @PutMapping("/permissoes") public ApiResponse<?> update(@RequestBody UpdateRequest r){admin.update(r);return ApiResponse.ok(java.util.Map.of("updated",true));}
 // Dados da loja (PIX): quem vende precisa ler para gerar o QR; só quem edita configurações altera.
 @GetMapping("/loja") public ApiResponse<ConfiguracaoLojaService.Dados> lojaGet(){permissions.page("vendas");return ApiResponse.ok(loja.dados());}
 @PutMapping("/loja") public ApiResponse<ConfiguracaoLojaService.Dados> lojaPut(@Valid @RequestBody ConfiguracaoLojaService.Dados d){permissions.action("configuracoes_editar");return ApiResponse.ok(loja.salvar(d));} }
